const evaluate=(d,s)=>{if(!d)return undefined;if(d.type==='VARIABLE_ALIAS')return s.values[typeof d.value==='object'?d.value.id:d.value];if(d.type==='EXPRESSION'){const args=d.value.expressionArguments.map(a=>evaluate(a,s));switch(d.value.expressionFunction){case'EQUALS':return args[0]===args[1];case'NOT_EQUAL':return args[0]!==args[1];case'AND':return args.every(Boolean);case'OR':return args.some(Boolean);case'NOT':return !args[0];case'ADDITION':return args[0]+args[1];case'SUBTRACTION':return args[0]-args[1];case'LESS_THAN':return args[0]<args[1];case'GREATER_THAN':return args[0]>args[1];case'LESS_THAN_OR_EQUAL':return args[0]<=args[1];case'GREATER_THAN_OR_EQUAL':return args[0]>=args[1];default:throw Error('unsupported expression '+d.value.expressionFunction);}}return d.value;};
const execute=(acts,s)=>{for(const a of acts){if(a.type==='SET_VARIABLE')s.values[a.variableId]=evaluate(a.variableValue,s);else if(a.type==='CONDITIONAL'){for(const b of a.conditionalBlocks)if(!b.condition||evaluate(b.condition,s)){execute(b.actions,s);break;}}else if(a.type==='NODE'){if(a.navigation==='NAVIGATE'||a.navigation==='OVERLAY')s.destinations.push([a.destinationId,a.navigation]);}else if(a.type==='CLOSE')s.closed=true;else if(a.type==='BACK')throw Error('browser back action in workspace history');}};
const click=n=>cleanRx(n.reactions).find(r=>r.trigger?.type==='ON_CLICK')?.actions||[];
const newSession=()=>({values:Object.fromEntries(Object.entries(V).map(([name,id])=>[id,name==='History/index'||name==='History/end'?0:name==='History/moving'?false:name.includes(' state')?'Disabled':''])),destinations:[],closed:false});
const value=(s,name)=>s.values[V[name]];
const run=a=>{const s=newSession();execute(a,s);return s;};

